package studio.gravigo

data class LoginState(
    val email: String = "",
    val isSubmitting: Boolean = false,
    val error: String? = null,
)

fun canSubmit(state: LoginState): Boolean {
    return state.email.contains("@") &&
        !state.isSubmitting
}

